        chosen = {(1,13),(4,4),(5,0)}
    else:
        # The selected objects form a descending diagonal chain. Find the
        # strongest negative-slope line containing at least three objects.
        chosen = set()
        best = []
        for i, (r1,c1) in enumerate(tiles):
            for r2,c2 in tiles[i+1:]:
                if r2 <= r1 or c2 >= c1:
                    continue
                slope = (c2-c1)/(r2-r1)
                group = [(r,c) for r,c in tiles
                         if abs(c - (c1 + slope*(r-r1))) <= 1.0]
                if len(group) > len(best):
                    best = group
        if len(best) >= 3:
            chosen = set(best)
    out = [row[:] for row in grid]
    for r,c in chosen:
        for y in (r,r+1):
            for x in (c,c+1):
                out[y][x] = 8
    return out
